#include <stdio.h>
#include <stdint.h>

#include "pse/pse.h"
#include "pse/pse.hpp"

int main() {
  printf("[SDK] Запуск и инициализация...\n");

  // 1. Подключаемся к Shared Memory, которую для нас уже создала игра
  // Если игра не запущена, функция вернет ошибку
  if (pseInitializeBuffers() != 0) { 
      printf("[SDK] Ошибка: Игра не запущена или Shared Memory недоступна!\n");
      return -1;
  }
  printf("[SDK] Успешно инициализировали память игры!\n");

  // 1: Инициализация игры
  {
      // Создаем пустую 64-байтовую структуру на стеке
      PseData data{};

      // [Команда] Инициализация игры
      data.header = PSE_COMMAND_GAME_INITIALIZE;

      printf("[SDK] Отправляем запрос на инициализацию...\n");

      // Отправляем команду и блокируем поток, пока игра не выполнит ее
      // Игра сотрет нашу команду и запишет результат прямо в эту же переменную data!
      pseCommandBufferSinglePushAndWait(&data);

      if (data.header != PSE_RESULT_SUCCESS) 
      {
          printf("[SDK] Ошибка инициализации игры! Код ошибки: 0x%08X\n", data.header);
          pseDeinitializeBuffers();
          return -1;
      }
      printf("[SDK] Игра успешно инициализирована!\n");
  }

  // 2: Создание динамического меша (плоскости)
  {
      // Создаем пустую 64-байтовую структуру на стеке
      PseData data{};

      // [Команда] Создать динамический меш
      data.header = PSE_COMMAND_DYNAMIC_MESH_CREATE;

      // Шаблон pse::Data::set<Смещение, Тип> красиво и безопасно упаковывает данные в сырые 60 байт полезной нагрузки
      // Никакого ручного сдвига байт - хелпер сам знает размеры типов

      // [Смещение  0] Позиция, поворот и масштаб объекта на сцене
      // Занимает первые 40 байт полезной нагрузки
      pse::Data::set<0, PseTransform>(
          data, 
          PseTransform{
              PseQuat{},                             // Поворот
              PseVector3{-400.0f, -400.0f, -100.0f}, // Координаты X, Y, Z
              PseVector3{1.0f, 1.0f, 1.0f}           // Масштаб
          }
      );

      // [Смещение 40] Задаем геометрию меша
      pse::Data::set<40, PseMesh>(data, PSE_MESH_FACE);

      // [Смещение 42] Задаем материал (текстуру пола)
      pse::Data::set<42, PseMaterial>(data, PSE_MATERIAL_FLOOR_WHITE);

      // [Смещение 44] Флаг видимости (Visibility). 1 - объект сразу отображается в игре
      pse::Data::set<44, int8_t>(data, 1);

      printf("[SDK] Отправляем команду на создание меша...\n");

      // Снова отправляем пакет в буфер и ждем ответа от игры
      pseCommandBufferSinglePushAndWait(&data);

      if (data.header != PSE_RESULT_SUCCESS)
      {
          printf("[SDK] Не удалось создать меш! Код ошибки: 0x%08X\n", data.header);
          pseDeinitializeBuffers();
          return -1;
      }
      printf("[SDK] Динамический меш успешно создан и отображен на сцене!\n");
  }

  // 3. Чистим за собой и корректно закрываем дескрипторы памяти перед выходом
  pseDeinitializeBuffers();
  printf("[SDK] Работа завершена. Отключено\n");
  return 0;
}

#include <stdio.h>
#include <stdint.h>

#include "pse/pse.h"
#include "pse/pse.hpp"

int main() {
  printf("[SDK] Starting and initializing...\n");

  // 1. Connect to the Shared Memory that the game has already created for us
  // If the game is not running, the function will return an error
  if (pseInitializeBuffers() != 0) { 
      printf("[SDK] Error: The game is not running or Shared Memory is unavailable!\n");
      return -1;
  }
  printf("[SDK] Successfully initialized the game memory!\n");

  // 1: Game initialization
  {
      // Create an empty 64-byte structure on the stack
      PseData data{};

      // [Command] Game initialization
      data.header = PSE_COMMAND_GAME_INITIALIZE;

      printf("[SDK] Sending the initialization request...\n");

      // Send the command and block the thread until the game executes it
      // The game will overwrite our command and write the result directly into this same data variable!
      pseCommandBufferSinglePushAndWait(&data);

      if (data.header != PSE_RESULT_SUCCESS) 
      {
          printf("[SDK] Game initialization failed! Error code: 0x%08X\n", data.header);
          pseDeinitializeBuffers();
          return -1;
      }
      printf("[SDK] Game successfully initialized!\n");
  }

  // 2: Creating a dynamic mesh (plane)
  {
      // Create an empty 64-byte structure on the stack
      PseData data{};

      // [Command] Create a dynamic mesh
      data.header = PSE_COMMAND_DYNAMIC_MESH_CREATE;

      // The pse::Data::set<Offset, Type> template nicely and safely packs data into the raw 60 bytes of payload
      // No manual byte shifting - the helper knows the type sizes itself

      // [Offset  0] Position, rotation and scale of the object on the scene
      // Occupies the first 40 bytes of payload
      pse::Data::set<0, PseTransform>(
          data, 
          PseTransform{
              PseQuat{},                             // Rotation
              PseVector3{-400.0f, -400.0f, -100.0f}, // X, Y, Z coordinates
              PseVector3{1.0f, 1.0f, 1.0f}           // Scale
          }
      );

      // [Offset 40] Set the mesh geometry
      pse::Data::set<40, PseMesh>(data, PSE_MESH_FACE);

      // [Offset 42] Set the material (floor texture)
      pse::Data::set<42, PseMaterial>(data, PSE_MATERIAL_FLOOR_WHITE);

      // [Offset 44] Visibility flag. 1 - the object is immediately displayed in the game
      pse::Data::set<44, int8_t>(data, 1);

      printf("[SDK] Sending the mesh creation command...\n");

      // Again send the packet to the buffer and wait for the game response
      pseCommandBufferSinglePushAndWait(&data);

      if (data.header != PSE_RESULT_SUCCESS)
      {
          printf("[SDK] Failed to create the mesh! Error code: 0x%08X\n", data.header);
          pseDeinitializeBuffers();
          return -1;
      }
      printf("[SDK] Dynamic mesh successfully created and displayed on the scene!\n");
  }

  // 3. Clean up after ourselves and correctly close the memory handles before exiting
  pseDeinitializeBuffers();
  printf("[SDK] Work finished. Disconnected\n");
  return 0;
}
